-- Replace the old mock course materials with the 100 sample lecture PDFs
-- (src/assets/course_pdfs_sample_pack). One PDF per row of course_pdf_index.csv,
-- attached to an offering of the matching course (round-robin when a course has several offerings).
-- Run after schema.sql + mockData.sql. file_path is relative to the project root (the app's working directory).

USE afms_db;

DELETE FROM course_material;
ALTER TABLE course_material AUTO_INCREMENT = 1;



-- Nothing may be dated after "today" (2026-11-01): pull the few later dates back two weeks.
UPDATE course_material SET upload_date = DATE_SUB(upload_date, INTERVAL 14 DAY)
WHERE upload_date > '2026-11-01 23:59:59';
